const lingkariHuruf = {
    id: "cal-lingkari-huruf",
    label: "Mengenal huruf (lingkari)",
    gen: (_lv, R)=>{
        const target = pick(R, [
            "b",
            "d",
            "p",
            "q",
            "c",
            "e",
            "a",
            "m",
            "n",
            "u",
            "g",
            "s"
        ]);
        const pengisi = "aceghkmnpqrsuvwdtzblfijo".split("").filter((x)=>x !== target);
        const huruf = [];
        for(let i = 0; i < 8; i++)huruf.push(i < 3 ? target : pick(R, pengisi));
        for(let i = huruf.length - 1; i > 0; i--){
            const j = Math.floor(R() * (i + 1));
            [huruf[i], huruf[j]] = [
                huruf[j],
                huruf[i]
            ];
        }
        const tampil = huruf.map((h)=>R() < 0.5 ? h : h.toUpperCase()).join("  ");
        return {
            q: `Lingkari semua huruf ${target.toUpperCase()} pada baris ini!  ${tampil}`,
            a: `3 huruf ${target.toUpperCase()}`
        };
    }
};
const sukuKata2 = {
    id: "cal-suku-kata",
    label: "Merangkai suku kata",
    gen: (lv, R)=>{
        const s = lv >= 2 ? pick(R, SUKU3) : pick(R, SUKU2);
        const acak = [
            ...s
        ];
        for(let i = acak.length - 1; i > 0; i--){
            const j = Math.floor(R() * (i + 1));
            [acak[i], acak[j]] = [
                acak[j],
                acak[i]
            ];
        }
        if (acak.join("") === s.join("")) [acak[0], acak[acak.length - 1]] = [
            acak[acak.length - 1],
            acak[0]
        ];
        return {
            q: "Rangkai suku kata menjadi kata yang benar!",
            a: s.join(""),
            kind: "urut",
            words: acak
        };
    }
};
const kataHilang = {
    id: "cal-kata-hilang",
    label: "Huruf yang hilang",
    gen: (lv, R)=>{
        const [kata, petunjuk] = pick(R, KATA_HILANG);
        const i = Math.max(1, Math.min(kata.length - 2, ri(R, 1, kata.length - 2) + (lv === 3 ? 1 : 0)));
        const tampil = kata.slice(0, i) + "_" + kata.slice(i + 1);
        return {
            q: `Huruf apa yang hilang?  ${tampil}  (petunjuk: ${petunjuk})`,
            a: kata[i]
        };
    }
};
