    const topiks = TOPIK_GENERATOR[mapel]?.[jenjang]?.[kelas] ?? [];
    if (!topiks.length) return [];
    const biasa = topiks.filter((t)=>!t.id.endsWith("-jodoh"));
    const perTopik = Math.max(2, Math.ceil(total / Math.max(1, biasa.length)));
